// Not a published package: a package in the `@solidjs` scope that defines
// none of Solid's primitives, only bindings spelled like them.

// Its own `flush`: runs `fn` and drains nothing of Solid's.
export function flush(fn) {
  fn();
}

// The shape of `@solidjs/router@2.0.0-next.41`'s `dist/preload.js:139-147`:
// a local `const flush = whenIdle(...)`, called inside the package.
function whenIdle(fn) {
  return () => {
    fn();
  };
}

export function preloadWhenIdle(load) {
  const flush = whenIdle(load);
  flush();
}

// Runs `apply` once, synchronously, on the caller's stack.
export function createEffect(source, apply) {
  apply(source());
}

// Calls a function tag once, synchronously, on the caller's stack.
export function useHead(tag) {
  return typeof tag === "function" ? tag() : tag;
}

// The shape of `@solidjs/router@2.0.0-next.41`'s `useAction(action)`
// (`dist/data/action.js:232-236`): the parameter is the caller's function.
export function useAction(action) {
  return (...args) => action.apply(null, args);
}
